import { z } from 'zod';
import type { Route } from './+types/profile';

const ProfileSchema = z.object({ username: z.string().min(3).max(30), bio: z.string().max(160).optional() });
export async function loader({ request }: Route.LoaderArgs) { return { user: { id: 'u1', username: 'alice' } }; }
export async function action({ request }: Route.ActionArgs) { const data = await request.formData(); const parsed = ProfileSchema.safeParse(Object.fromEntries(data)); if (!parsed.success) return { errors: parsed.error.flatten() }; return { ok: true }; }
export default function Profile({ loaderData }: Route.ComponentProps) { return <div><h1>Profile {loaderData.user.username}</h1></div>; }
